import{c as e,Q as t,j as i,m as n}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"Why Do Multi-Agent LLM Systems Fail?","description":"","frontmatter":{"url":"https://arxiv.org/abs/2503.13657","title":"Why Do Multi-Agent LLM Systems Fail?","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2503.13657,"authors":["Mert Cemri","Melissa Z. Pan","Shuyi Yang","Lakshya A. Agrawal","Bhavya Chopra","Rishabh Tiwari","Kurt Keutzer","Aditya Parameswaran","Dan Klein","Kannan Ramchandran","Matei Zaharia","Joseph E. Gonzalez","Ion Stoica"],"domains":["cs.AI","cs.MA","cs.CL"],"pdf_path":"pdfs/2503.13657.pdf","published_date":"2025-03-17T00:00:00.000Z","tags":["multi-agent","failure-taxonomy","mast","benchmark","reliability","llm"],"venue":"NeurIPS 2025 Datasets & Benchmarks"},"headers":[],"relativePath":"research/papers/2025-03-17-mast-why-multi-agent-llm-systems-fail-2503-13657.md","filePath":"research/papers/2025-03-17-mast-why-multi-agent-llm-systems-fail-2503-13657.md","lastUpdated":1785909234000}'),r={name:"research/papers/2025-03-17-mast-why-multi-agent-llm-systems-fail-2503-13657.md"};function s(o,a,l,m,g,h){return t(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="why-do-multi-agent-llm-systems-fail" tabindex="-1">Why Do Multi-Agent LLM Systems Fail? <a class="header-anchor" href="#why-do-multi-agent-llm-systems-fail" aria-label="Permalink to &quot;Why Do Multi-Agent LLM Systems Fail?&quot;">​</a></h1><p><strong>arXiv</strong>: 2503.13657 | <strong>發表</strong>: 2025-03-17 | <strong>PDF</strong>: 2025-03-17-mast-why-multi-agent-llm-systems-fail-2503-13657.pdf</p><h2 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h2><p>UC Berkeley 等提出 <strong>MAST（Multi-Agent System Failure Taxonomy）</strong>：首個實驗性多 agent 失敗模式分類框架。分析 7 個主流 MAS 框架（AutoGen、CrewAI、LangGraph 等）× 200+ 任務，人工標注 150 條 traces，歸納 14 個失敗模式，inter-annotator agreement κ = 0.88。NeurIPS 2025 Datasets &amp; Benchmarks Track。</p><h2 id="方法-架構" tabindex="-1">方法 / 架構 <a class="header-anchor" href="#方法-架構" aria-label="Permalink to &quot;方法 / 架構&quot;">​</a></h2><ul><li><strong>MAST-Data</strong>：1,600+ 標注 traces，跨 7 個框架 × 多模型（GPT-4、Claude 3、Qwen2.5、CodeLlama）× 三類任務（coding、math、general agent）</li><li><strong>14 種失敗模式</strong>，分三大類： <ul><li><strong>(i) Specification Issues</strong>：任務規格不清、工具描述錯誤、角色定義歧義</li><li><strong>(ii) Inter-Agent Misalignment</strong>：agent 間目標不一致、資訊傳遞失真、責任歸屬不明</li><li><strong>(iii) Task Verification</strong>：無法判斷任務完成狀態、幻覺式自我報告完成</li></ul></li><li><strong>LLM-as-Judge pipeline</strong>：可自動標注新 traces，驗證與人工標注高度一致</li><li><strong>Improvement Headroom 分析</strong>：每個失敗模式標注潛在提升空間，作為設計優先順序依據</li></ul><h2 id="關鍵發現與數據" tabindex="-1">關鍵發現與數據 <a class="header-anchor" href="#關鍵發現與數據" aria-label="Permalink to &quot;關鍵發現與數據&quot;">​</a></h2><ul><li>7 個框架在 benchmark 上的提升相對單 agent <strong>常常很小甚至為負</strong>，揭示 MAS 效能增益被誇大</li><li>Task Verification 是最難自動修復的類別：agent 無法可靠判斷自己是否完成任務</li><li>Inter-Agent Misalignment 在 hierarchical 架構中特別顯著（coordinator 與 worker 目標漂移）</li><li>跨框架、跨模型、跨任務類型，失敗分佈高度一致，表明問題是結構性而非模型特定</li></ul><h2 id="對-agent-team-設計的啟示" tabindex="-1">對 agent-team 設計的啟示 <a class="header-anchor" href="#對-agent-team-設計的啟示" aria-label="Permalink to &quot;對 agent-team 設計的啟示&quot;">​</a></h2><ol><li><strong>Specification 品質是 MAS 天花板</strong>：工具描述、角色定義、任務分解的歧義度直接決定失敗率，在設計階段解決比 agent 數量更重要</li><li><strong>需要外部 verification oracle</strong>：agent 自我報告「完成」不可信（對應 R4 完成條件必須可機械驗證）</li><li><strong>inter-agent misalignment 在 hierarchical 架構是系統性風險</strong>：coordinator 指令需要 structured handoff + confirmation，不能依賴 agent 自行解讀</li></ol><h2 id="原文關鍵引用-≤150字" tabindex="-1">原文關鍵引用（≤150字） <a class="header-anchor" href="#原文關鍵引用-≤150字" aria-label="Permalink to &quot;原文關鍵引用（≤150字）&quot;">​</a></h2><blockquote><p>&quot;Despite growing enthusiasm, performance gains on popular benchmarks often remain minimal compared with single-agent frameworks... We develop MAST, the first empirically grounded taxonomy for understanding MAS failures. MAST was developed through rigorous analysis of 150 traces, guided closely by expert human annotators and validated by high inter-annotator agreement (κ = 0.88). We identify 14 unique failure modes organized into 3 overarching categories: specification issues, inter-agent misalignment, and task verification.&quot;</p></blockquote>',12)])])}const u=e(r,[["render",s]]);export{d as __pageData,u as default};
